head.script:
scwin.screenId = "jldfil25004";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil25004.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////



///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.goDsclInsert
 * @author Inswave
 * @date 2026. 09. 29
 * @param formKorNm
 * @returns
 * @hidden N
*/
scwin.goDsclInsert = function (formKorNm) {
    /* sdd-asis-lifecycle:begin fn_GoDsclInsert — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (document.disclosureForm || { elements: [] }).formKorNm.value = formKorNm;
    /* 수동 전환 필요: 폼 disclosureForm 제출 — action 미보유 */ document.disclosureForm.submit();
    /* sdd-asis-lifecycle:end */
};
